import openpyxl
inp='/tmp/llm_rollout_qu8tyc8t/3_55912_answer_template_3722_input.xlsx'
gold='/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/3_55912_answer_template_3722_golden.xlsx'
wbi=openpyxl.load_workbook(inp, data_only=False)
wbg=openpyxl.load_workbook(gold, data_only=False)
diffs=[]
for sheet in wbi.sheetnames:
    wsi=wbi[sheet]; wsg=wbg[sheet]
    coords=set()
    for row in wsi.iter_rows():
        for c in row:
            if c.value is not None or True:
                coords.add(c.coordinate)
    for row in wsg.iter_rows():
        for c in row:
            coords.add(c.coordinate)
    for coord in sorted(coords, key=lambda x:(int(''.join(filter(str.isdigit,x))), x)):
        ci=wsi[coord]; cg=wsg[coord]
        # compare
        dif=False; desc=[]
        # value/formula
        vi=ci.value; vg=cg.value
        if vi!=vg:
            dif=True; desc.append(f'value {vi!r} -> {vg!r}')
        # style
        si=ci.style_id; sg=cg.style_id
        if si!=sg:
            dif=True; desc.append(f'style {si}->{sg}')
        if dif:
            diffs.append((sheet,coord,desc))
print('total diffs', len(diffs))
for d in diffs:
    print(d)
