    fc=cc=0
    for row in ws.iter_rows():
        for c in row:
            if c.value is None: continue
            if isinstance(c.value,str) and c.value.startswith('='):
                fc+=1
            elif hasattr(c.value,'text'):
                fc+=1
            else:
                cc+=1
